import assert from "node:assert/strict";
import { test } from "node:test";
import { CREATURES } from "../../dist/public/sim/data/creatures.js";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import { resolveCombat } from "../../dist/public/sim/combat.js";
import { newMapRun } from "../../dist/public/sim/run.js";
import { programFromRules } from "./program-fixture.mjs";

const [mapId, map] = Object.entries(MAPS)[0];

function encounter(action, backpack = {}) {
  const program = programFromRules({
    condition: { kind: "always" },
    action: { kind: action },
  });
  const run = newMapRun(map, 1, program, { mapId, characterId: 1 }).run;
  return {
    run: {
      ...run,
      character: {
        ...run.character,
        backpack: { ...run.character.backpack, ...backpack },
      },
    },
    program,
  };
}

function runWithProgram(program, backpack = {}) {
  const run = newMapRun(map, 1, program, { mapId, characterId: 1 }).run;
  return {
    ...run,
    character: {
      ...run.character,
      backpack: { ...run.character.backpack, ...backpack },
    },
  };
}

test("four stick strikes defeat the wolf after three bites, leaving 79 health", () => {
  const { run, program } = encounter("strikeWithStick", { stick: 1 });
  const runBefore = structuredClone(run);
  const programBefore = structuredClone(program);
  const mapBefore = structuredClone(map);
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.creatureHealth, 0);
  assert.equal(result.characterHealth, 79);
  assert.equal(result.outcome, "creatureDefeated");
  assert.equal(result.exchanges.length, 4);
  assert.equal(result.exchanges[3].creatureAction.kind, "dodge");
  assert.equal(result.ruleStarts[1], 4);
  assert.equal(run.body.health, 100);
  assert.equal(run.character.backpack.stick, 1);
  assert.deepEqual(run, runBefore);
  assert.deepEqual(program, programBefore);
  assert.deepEqual(map, mapBefore);
  assert.equal(CREATURES.wolf.health, 24);
});

test("eight kicks defeat the wolf after six bites, leaving 58 health", () => {
  const { run, program } = encounter("kick");
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.creatureHealth, 0);
  assert.equal(result.characterHealth, 58);
  assert.equal(result.outcome, "creatureDefeated");
  assert.equal(result.exchanges.length, 8);
});

test("no feasible combat rule loses each action and the fifteenth bite kills", () => {
  const program = programFromRules();
  const run = runWithProgram(program);
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.outcome, "characterDied");
  assert.equal(result.characterHealth, 0);
  assert.equal(result.creatureHealth, 24);
  assert.equal(result.exchanges.length, 15);
  assert.ok(
    result.exchanges.every((exchange) => exchange.characterAction === null),
  );
  assert.deepEqual(result.ruleStarts, {});
});

test("a lethal opening strike ends the exchange before the character can act", () => {
  const { run, program } = encounter("kick");
  const woundedRun = { ...run, body: { ...run.body, health: 7 } };
  const result = resolveCombat(woundedRun, map, "wolf", program);

  assert.equal(result.outcome, "characterDied");
  assert.equal(result.characterHealth, 0);
  assert.equal(result.exchanges.length, 1);
  assert.equal(result.exchanges[0].characterAction, null);
  assert.deepEqual(result.ruleStarts, {});
});

test("forty dodges use one refreshed reduction and leave the wolf at 15 health", () => {
  const { run, program } = encounter("dodge");
  const result = resolveCombat(run, map, "wolf", program);

  assert.equal(result.outcome, "creatureDeparted");
  assert.equal(result.creatureHealth, 24);
  assert.equal(result.characterHealth, 15);
  assert.equal(result.exchanges.length, 40);
  assert.equal(result.exchanges[0].creatureAction.damage, 7);
  assert.ok(
    result.exchanges
      .slice(1)
      .every((exchange) => exchange.creatureAction.damage === 2),
  );
});

test("a stick strike without a stick is skipped in favor of the next combat rule", () => {
  const program = programFromRules(
    { condition: { kind: "always" }, action: { kind: "strikeWithStick" } },
    { condition: { kind: "always" }, action: { kind: "kick" } },
  );
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.deepEqual(result.exchanges[0].characterAction, {
    ruleId: 2,
    action: { kind: "kick" },
    damage: 3,
    creatureHealth: 21,
    characterHealth: 93,
  });
  assert.deepEqual(result.ruleStarts, { 2: 8 });
});

test("ordinary actions cannot be carried out during combat", () => {
  const program = programFromRules({
    condition: { kind: "always" },
    action: { kind: "explore" },
  });
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.equal(result.exchanges[0].characterAction, null);
  assert.deepEqual(result.ruleStarts, {});
});

test("character health conditions are checked after the creature's strike", () => {
  const program = programFromRules({
    condition: { kind: "healthBelow", value: 94 },
    action: { kind: "kick" },
  });
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.equal(result.exchanges[0].creatureAction.characterHealth, 93);
  assert.equal(result.exchanges[0].characterAction.action.kind, "kick");
  assert.equal(result.ruleStarts[1], 8);
});

test("combat checks group conditions in order against post-strike health", () => {
  const always = { kind: "always" };
  const kick = { kind: "kick" };
  const program = {
    groups: [
      {
        id: 1,
        name: "Wounded",
        condition: { kind: "healthBelow", value: 94 },
        rules: [{ id: 11, condition: always, action: kick }],
      },
      {
        id: 2,
        name: "Fallback",
        condition: always,
        rules: [{ id: 22, condition: always, action: kick }],
      },
    ],
    nextGroupId: 3,
    nextRuleId: 23,
  };
  const result = resolveCombat(runWithProgram(program), map, "wolf", program);

  assert.equal(result.exchanges[0].characterAction.ruleId, 11);
  assert.equal(result.ruleStarts[11], 8);
  assert.equal(result.ruleStarts[22], undefined);
});

tests/sim/completion.test.mjs.source:
// The completion of a map run: when the streak reaches the solving condition of the map, the rest of
// that game minute takes effect, no program rule is picked and the map run ends, solving its map.
// Expectations come from the task "rozwiazanie-lasu", To do 5 and 7 and Questions to settle 6, 8,
// 15 and 17 (task.md lines 19-22, 42-50, 66-71, 75-77); the streak of 480 is the solving condition
// of Las (D-80), a streak of 479 stands one game minute short of it.
import assert from "node:assert/strict";
import { test } from "node:test";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  advanceMinutes,
  canSendMap,
  createCharacter,
  end,
  newGame,
  passRealTime,
  restart,
  send,
  setProgram,
} from "../../dist/public/sim/game.js";
import { sameHex } from "../../dist/public/sim/hex.js";
import { meetsSolving } from "../../dist/public/sim/run.js";
import { programFromRules } from "./program-fixture.mjs";
import { newKnowingGame } from "./understanding-fixture.mjs";

const [mapId] = Object.keys(MAPS);
const SENT = { mapId, characterId: 1 };
const REAL_MS = 1760000000000;
const EXPLORING = programFromRules({
  condition: { kind: "always" },
  action: { kind: "explore" },
});
const EXPLORE = { kind: "explore" };
const HEALTHY = { temperature: 37, satiety: 100, health: 100 };

/** A game sent to Las with a program that explores; the map run stands at minute 0. */
function sent(game = newKnowingGame()) {
  const ready = createCharacter(setProgram(game, EXPLORING).state, "Ala").state;
  return send(ready, SENT, REAL_MS).state;
}

/** The sent game with the fields of its map run replaced. */
function withRun(fields, game) {
  const state = sent(game);
  return { ...state, run: { ...state.run, ...fields } };
}

/** The explore activity of the map run, ending in the next game minute. */
function endingNext(run) {
  return {
    activity: { kind: "rule", ruleId: 1, action: EXPLORE },
    startMinute: run.minute,
    endMinute: run.minute + 1,
    stepTo: null,
  };
}

/** A healthy map run whose streak stands at 479 and whose exploration ends in the next minute. */
function oneShort(game) {
  const run = sent(game).run;
  return withRun(
    { body: { ...HEALTHY }, streak: 479, current: endingNext(run) },
    game,
  );
}

/** A tile that is not the character's, for a campfire burning away from it. */
function otherTile(run) {
  return run.tiles.find((tile) => !sameHex(tile.at, run.character.at)).at;
}

const kinds = (events) => events.map((event) => event.kind);

test("a map run with a streak of 479 completes at the end of the next game minute without a loss, with the rest of that minute taken effect and no program rule picked", () => {
  const before = oneShort();
  const at = otherTile(before.run);
  const state = {
    ...before,
    run: { ...before.run, campfires: [{ at, minutesLeft: 10 }] },
  };
  const result = advanceMinutes(state, 5);
  const run = result.state.run;
  assert.equal(run.minute, 1, "the span stops at the completion");
  assert.equal(run.streak, 480);
  assert.deepEqual(run.completion, { minute: 1 });
  assert.equal(run.death, null);
  assert.deepEqual(
    run.campfires,
    [{ at, minutesLeft: 9 }],
    "burning took its minute",
  );
  assert.deepEqual(
    run.current,
    before.run.current,
    "no program rule was picked",
  );
  assert.deepEqual(result.events, [
    {
      kind: "activityFinished",
      minute: 1,
      activity: before.run.current.activity,
    },
    { kind: "tileRevealed", minute: 1, at: before.run.character.at },
    { kind: "mapRunCompleted", minute: 1 },
  ]);
  assert.ok(!kinds(result.events).includes("activityStarted"));
  assert.equal(result.state.paused, false);
  assert.equal(result.state.discovery, null);
  assert.deepEqual(result.state.solvedMaps, [mapId]);
});

test("a streak of 478 completes nothing in the next minute and the pick goes on", () => {
  const state = { ...oneShort(), run: { ...oneShort().run, streak: 478 } };
  const result = advanceMinutes(state, 1);
  assert.equal(result.state.run.streak, 479);
  assert.equal(result.state.run.completion, null);
  assert.deepEqual(result.state.solvedMaps, []);
  assert.ok(kinds(result.events).includes("activityStarted"));
});

test("a minute of loss from a streak of 479 does not complete", () => {
  const state = withRun({
    body: { temperature: 34.99, satiety: 100, health: 100 },
    streak: 479,
  });
  const result = advanceMinutes(state, 1);
  assert.equal(result.state.run.streak, 0);
  assert.equal(result.state.run.completion, null);
  assert.deepEqual(result.state.solvedMaps, []);
});

test("a new game and a new map run hold no completion and no solved map", () => {
  assert.deepEqual(newGame().solvedMaps, []);
  assert.equal(sent().run.completion, null);
});

test("a map run that has completed passes no further game minute, by span or by real time", () => {
  const done = advanceMinutes(oneShort(), 1).state;
  const again = advanceMinutes(done, 10);
  assert.deepEqual(again.state, done);
  assert.deepEqual(again.events, []);
  const timed = passRealTime(done, 60000);
  assert.deepEqual(timed.state, done);
  assert.deepEqual(timed.events, []);
});

test("real time that ends in a completion stops there and drops the whole carry", () => {
  const state = { ...oneShort(), realMsCarry: 400 };
  const result = passRealTime(state, 5600);
  assert.equal(result.state.run.minute, 1);
  assert.deepEqual(result.state.run.completion, { minute: 1 });
  assert.equal(result.state.realMsCarry, 0);
  assert.equal(result.events.at(-1).kind, "mapRunCompleted");
  assert.equal(result.state.paused, false);
});

test("the completion in the minute of a discovery leaves the state holding the discovery, not paused", () => {
  const unknowing = {
    ...newGame(),
    understanding: {
      actions: [],
      conditions: ["always"],
      items: [],
      creatures: [],
    },
  };
  const result = advanceMinutes(oneShort(unknowing), 5);
  const found = result.events.findIndex((event) => event.kind === "discovered");
  const completed = result.events.findIndex(
    (event) => event.kind === "mapRunCompleted",
  );
  assert.ok(found >= 0, "precondition: the minute discovered something");
  assert.ok(completed > found, "the completion follows the discovery");
  assert.equal(result.events.length, completed + 1);
  assert.equal(result.state.run.minute, 1);
  assert.deepEqual(result.state.run.completion, { minute: 1 });
  assert.equal(result.state.paused, false);
  assert.deepEqual(result.state.discovery, {
    actions: result.events[found].actions,
    conditions: result.events[found].conditions,
    items: result.events[found].items,
    creatures: [],
  });
  const revealed = result.events[found];
  for (const kind of ["actions", "conditions", "items"])
    for (const entry of revealed[kind])
      assert.ok(result.state.understanding[kind].includes(entry), entry);
  assert.deepEqual(result.state.solvedMaps, [mapId]);
});

test("a map solved stays solved, once, through restart, end, send and a later death", () => {
  const solved = advanceMinutes(oneShort(), 1).state;
  assert.deepEqual(restart(solved).state.solvedMaps, [mapId]);
  const ended = end(solved).state;
  assert.deepEqual(ended.solvedMaps, [mapId]);
  assert.deepEqual(send(ended, SENT, REAL_MS).state.solvedMaps, [mapId]);

  // A later map run on the same map completes again and the map is listed once.
  const second = restart(solved).state;
  const again = {
    ...second,
    run: {
      ...second.run,
      body: { ...HEALTHY },
      streak: 479,
      current: endingNext(second.run),
    },
  };
  assert.deepEqual(advanceMinutes(again, 1).state.solvedMaps, [mapId]);

  // A later map run that ends in death leaves the map solved.
  const dying = {
    ...second,
    run: {
      ...second.run,
      body: { temperature: 34, satiety: 50, health: 0.7 },
      streak: 5,
    },
  };
  const died = advanceMinutes(dying, 30).state;
  assert.ok(died.run.death);
  assert.equal(died.run.completion, null);
  assert.deepEqual(died.solvedMaps, [mapId]);
});

test("restart after a completion keeps the seed and starts with a streak of 0 and no completion", () => {
  const solved = advanceMinutes(oneShort(), 1).state;
  const restarted = restart(solved);
  assert.equal(restarted.state.run.seed, solved.run.seed);
  assert.equal(restarted.state.run.minute, 0);
  assert.equal(restarted.state.run.streak, 0);
  assert.equal(restarted.state.run.completion, null);
  assert.equal(restarted.state.paused, false);
  assert.equal(restarted.events[0].kind, "mapRunEnded");
});

test("the counts of the rules stay after a completion, through end", () => {
  const state = oneShort();
  assert.deepEqual(state.ruleCounts, { 1: 1 });
  const solved = advanceMinutes(state, 1).state;
  assert.deepEqual(solved.ruleCounts, { 1: 1 });
  assert.deepEqual(end(solved).state.ruleCounts, { 1: 1 });
});

test("the program edited on a map run that has completed leaves its streak at 480", () => {
  const solved = advanceMinutes(oneShort(), 1).state;
  const edited = setProgram(
    solved,
    programFromRules(
      { condition: { kind: "always" }, action: { kind: "explore" } },
      { condition: { kind: "always" }, action: { kind: "wander" } },
    ),
  ).state;
  assert.equal(edited.run.streak, 480);
  assert.deepEqual(edited.run.completion, { minute: 1 });
});

test("solving requirements present in data are all required and absent ones are ignored", () => {
  const deep = MAPS.forestDeep;
  const run = {
    ...sent().run,
    mapId: "forestDeep",
    streak: 539,
    defeatedAttacks: 1,
  };
  assert.equal(meetsSolving(run, deep), false);
  assert.equal(meetsSolving({ ...run, streak: 540 }, deep), false);
  assert.equal(meetsSolving({ ...run, defeatedAttacks: 2 }, deep), false);
  assert.equal(
    meetsSolving({ ...run, streak: 540, defeatedAttacks: 2 }, deep),
    true,
  );
  assert.equal(
    meetsSolving(
      { ...run, defeatedAttacks: 1 },
      { ...deep, solving: { defeatedAttacks: 2 } },
    ),
    false,
  );
  assert.equal(
    meetsSolving(
      { ...run, defeatedAttacks: 2 },
      { ...deep, solving: { defeatedAttacks: 2 } },
    ),
    true,
  );
  assert.equal(meetsSolving({ ...run, streak: 480 }, MAPS.forest), true);
});

test("a map is sendable only after each map it opens after is solved", () => {
  assert.deepEqual(canSendMap([], "forest"), true);
  assert.deepEqual(canSendMap([], "forestDeep"), false);
  assert.deepEqual(canSendMap(["forest"], "forestDeep"), true);
  assert.throws(
    () =>
      send(
        createCharacter(newGame(), "Ala").state,
        { mapId: "forestDeep", characterId: 1 },
        REAL_MS,
      ),
    /not available/,
  );
});

test("an actual program edit resets the streak and defeated attacks; cold loss keeps defeated attacks", () => {
  const prepared = { ...end(sent()).state, solvedMaps: ["forest"] };
  const deeper = send(
    prepared,
    { mapId: "forestDeep", characterId: 1 },
    REAL_MS,
  ).state;
  const progressed = {
    ...deeper,
    run: {
      ...deeper.run,
      streak: 120,
      defeatedAttacks: 1,
      body: { ...HEALTHY, temperature: 34.99 },
    },
  };
  const changed = setProgram(
    progressed,
    programFromRules({
      condition: { kind: "always" },
      action: { kind: "wander" },
    }),
  ).state;
  assert.equal(changed.run.streak, 0);
  assert.equal(changed.run.defeatedAttacks, 0);

  const lostHealth = advanceMinutes(progressed, 1).state;
  assert.equal(lostHealth.run.streak, 0);
  assert.equal(lostHealth.run.defeatedAttacks, 1);
});

tests/sim/conditions.test.mjs.source:
import assert from "node:assert/strict";
import { test } from "node:test";
import { ITEMS } from "../../dist/public/sim/data/items.js";
import { MAPS } from "../../dist/public/sim/data/maps.js";
import {
  neighbours,
  offsetToAxial,
  sameHex,
} from "../../dist/public/sim/hex.js";
import {
  createCharacter,
  newGame,
  send,
  setProgram,
} from "../../dist/public/sim/game.js";
import { conditionHolds } from "../../dist/public/sim/program.js";
import { newMapRun } from "../../dist/public/sim/run.js";
import { programFromRules, programRules } from "./program-fixture.mjs";

// The conditions on the body, the backpack and the campfire (task, To do 12–13; spec Decision 3;
// D-26, D-57). Every number below is written out by hand from the spec's table: „Temperatura
// poniżej” takes 30.0 to 37.0 °C in steps of 0.1, „Sytość poniżej” 0 to 100 %, „Zapas poniżej”
// 0 to 50 pieces, „Zostało mniej niż — ognisko” 0 to 120 minutes and „Tu leży mniej niż” 0 to 50
// pieces, each of these four in steps of 1; „Z dala od — ognisko” takes no number.

const [mapId, forest] = Object.entries(MAPS)[0];
// The first character a new game creates takes the id 1.
const characterId = 1;
const [resource] = forest.resources.map((each) => each.id);
const [firstItem, secondItem] = Object.keys(ITEMS);
const entrance = offsetToAxial(forest.entrance.col, forest.entrance.row);
const SENT = { mapId, characterId };
const REAL_MS = 1760000000000;

const ALWAYS = { kind: "always" };
const EXPLORE = { kind: "explore" };
const rule = (condition, action) => ({ condition, action });
const temperatureBelow = (value) => ({ kind: "temperatureBelow", value });
const satietyBelow = (value) => ({ kind: "satietyBelow", value });
const itemBelow = (item, value) => ({ kind: "itemBelow", item, value });
const campfireLeftBelow = (value) => ({ kind: "campfireLeftBelow", value });
const healthBelow = (value) => ({ kind: "healthBelow", value });
const opponentHealthBelow = (value) => ({ kind: "opponentHealthBelow", value });
const AWAY = { kind: "awayFromCampfire" };
const hereBelow = (value) => ({ kind: "hereBelow", resource, value });

/** A map run of Las at minute 0 with no program rules, with the given fields replaced. */
function handMade(fields = {}) {
  const { run } = newMapRun(forest, 3, programFromRules(), {
    mapId,
    characterId,
  });
  return { ...run, ...fields };
}

const withBody = (temperature, satiety) =>
  handMade({ body: { temperature, satiety, health: 100 } });

/** A run whose backpack holds the given pieces and nothing else. */
function carrying(pieces) {
  const run = handMade();
  const empty = Object.fromEntries(
    Object.keys(run.character.backpack).map((id) => [id, 0]),
  );
  return {
    ...run,
    character: { ...run.character, backpack: { ...empty, ...pieces } },
  };
}

const holds = (run, condition) => conditionHolds(run, forest, condition);

test("health conditions compare the acting side and its opponent in health points", () => {
  const woundedWolf = { health: 6, opponentHealth: 100 };
  assert.equal(
    conditionHolds(handMade(), forest, healthBelow(8), woundedWolf),
    true,
  );
  assert.equal(
    conditionHolds(handMade(), forest, healthBelow(6), woundedWolf),
    false,
    "the threshold is strict",
  );
  assert.equal(
    conditionHolds(handMade(), forest, opponentHealthBelow(101), woundedWolf),
    true,
  );
  assert.equal(
    conditionHolds(handMade(), forest, opponentHealthBelow(100), woundedWolf),
    false,
    "the opponent threshold is strict",
  );
  assert.equal(holds(withBody(37, 100), healthBelow(101)), true);
  assert.equal(holds(handMade(), opponentHealthBelow(101)), false);
});

test("„Temperatura poniżej N °C” holds below N and not at N, also for tenths", () => {
  assert.equal(holds(withBody(34.999999, 100), temperatureBelow(35)), true);
  assert.equal(holds(withBody(35, 100), temperatureBelow(35)), false);
  assert.equal(holds(withBody(36.59, 100), temperatureBelow(36.6)), true);
  assert.equal(holds(withBody(36.6, 100), temperatureBelow(36.6)), false);
  assert.equal(holds(withBody(36.61, 100), temperatureBelow(36.6)), false);
});

test("„Sytość poniżej N %” holds below N and not at N", () => {
  assert.equal(holds(withBody(37, 29.999999), satietyBelow(30)), true);
  assert.equal(holds(withBody(37, 30), satietyBelow(30)), false);
  assert.equal(holds(withBody(37, 0), satietyBelow(0)), false);
  assert.equal(holds(withBody(37, 100), satietyBelow(100)), false);
  assert.equal(holds(withBody(37, 99.4), satietyBelow(100)), true);
});

test("„Zapas poniżej N szt.” counts only the named item of the backpack", () => {
  assert.equal(
    holds(carrying({ [firstItem]: 2 }), itemBelow(firstItem, 3)),
    true,
  );
  assert.equal(
    holds(carrying({ [firstItem]: 3 }), itemBelow(firstItem, 3)),
    false,
  );
  assert.equal(
    holds(carrying({ [secondItem]: 9 }), itemBelow(firstItem, 1)),
    true,
    "pieces of another item do not count",
  );
  assert.equal(
    holds(carrying({ [firstItem]: 9 }), itemBelow(secondItem, 1)),
    true,
  );
  assert.equal(holds(carrying({}), itemBelow(firstItem, 0)), false);
});

test("„Zostało mniej niż N min — ognisko” reads 0 where there is no campfire", () => {
  assert.equal(holds(handMade(), campfireLeftBelow(1)), true);
  assert.equal(holds(handMade(), campfireLeftBelow(0)), false);
});

test("„Zostało mniej niż N min — ognisko” reads the minutes left to a campfire on the character's tile", () => {
  const here = (minutesLeft) =>
    handMade({ campfires: [{ at: entrance, minutesLeft }] });
  assert.equal(holds(here(20), campfireLeftBelow(20)), false);
  assert.equal(holds(here(20), campfireLeftBelow(21)), true);
  assert.equal(holds(here(0), campfireLeftBelow(1)), true, "extinguished");
  assert.equal(holds(here(0), campfireLeftBelow(0)), false);
});

test("„Zostało mniej niż N min — ognisko” reads the nearest campfire, extinguished or not, not a farther one", () => {
  // Every tile costs 10 minutes to enter, so the neighbour is the nearer of the two.
  const run = handMade();
  const tiles = run.tiles.map((tile) => ({ ...tile, stepMinutes: 10 }));
  const [near] = neighbours(tiles, entrance);
  const far = tiles.find(
    (tile) =>
      !sameHex(tile.at, entrance) &&
      !neighbours(tiles, entrance).some((n) => sameHex(n.at, tile.at)),
  );
  const fires = (nearMinutes, farMinutes) =>
    handMade({
      tiles,
      campfires: [
        { at: far.at, minutesLeft: farMinutes },
        { at: near.at, minutesLeft: nearMinutes },
      ],
    });
  assert.equal(holds(fires(5, 100), campfireLeftBelow(6)), true);
  assert.equal(holds(fires(5, 100), campfireLeftBelow(5)), false);
  assert.equal(
    holds(fires(0, 100), campfireLeftBelow(1)),
    true,
    "the nearest is extinguished, a farther one burns",
  );
  assert.equal(holds(fires(100, 0), campfireLeftBelow(100)), false);
});

test("„Zostało mniej niż N min — ognisko” counts nearness in game minutes of walking, not in tiles", () => {
  // Every tile costs 10 minutes to enter but the neighbour `slow`, which costs 100: a tile two
  // tiles away through another neighbour is 20 minutes away, `slow` 100.
  const run = handMade();
  const [slow, other] = neighbours(run.tiles, entrance);
  const twoAway = neighbours(run.tiles, other.at).find(
    (tile) =>
      !sameHex(tile.at, entrance) &&
      !neighbours(run.tiles, entrance).some((n) => sameHex(n.at, tile.at)),
  );
  const tiles = run.tiles.map((tile) => ({
    ...tile,
    stepMinutes: sameHex(tile.at, slow.at) ? 100 : 10,
  }));
  const fires = handMade({
    tiles,
    campfires: [
      { at: slow.at, minutesLeft: 5 },
      { at: twoAway.at, minutesLeft: 60 },
    ],
  });
  assert.equal(holds(fires, campfireLeftBelow(60)), false);
  assert.equal(holds(fires, campfireLeftBelow(61)), true);
});

test("„Z dala od — ognisko” holds where no campfire stands on the character's tile", () => {
  const [near] = neighbours(handMade().tiles, entrance);
  assert.equal(holds(handMade(), AWAY), true, "no campfire");
  assert.equal(
    holds(handMade({ campfires: [{ at: near.at, minutesLeft: 30 }] }), AWAY),
    true,
    "a campfire on a neighbouring tile",
  );
  for (const minutesLeft of [0, 30]) {
    assert.equal(
      holds(handMade({ campfires: [{ at: entrance, minutesLeft }] }), AWAY),
      false,
      `a campfire with ${minutesLeft} minutes on the character's tile`,
    );
  }
});

/** The program `setProgram` holds after taking `condition` in, on the sending screen and in a run. */
function held(condition) {
  const program = programFromRules(rule(condition, EXPLORE));
  const running = send(
    createCharacter(newGame(), "Ala").state,
    SENT,
    REAL_MS,
  ).state;
  return [newGame(), running].map(
    (state) =>
      programRules(setProgram(state, program).state.program)[0].condition,
  );
}

function refused(condition) {
  const running = send(
    createCharacter(newGame(), "Ala").state,
    SENT,
    REAL_MS,
  ).state;
  for (const state of [newGame(), running]) {
    assert.throws(
      () => setProgram(state, programFromRules(rule(condition, EXPLORE))),
      Error,
      JSON.stringify(condition),
    );
  }
}

test("the check takes a temperature with tenths and holds it as the decimal the player reads", () => {
  for (const [offered, kept] of [
    [36.6, 36.6],
    [30.0, 30],
    [37, 37],
    [36.5, 36.5],
    [36.60000000000001, 36.6],
    [30.000000000000004, 30],
  ]) {
    for (const condition of held(temperatureBelow(offered))) {
      assert.deepEqual(condition, temperatureBelow(kept), String(offered));
      assert.equal(String(condition.value), String(kept));
    }
  }
});

test("the check refuses a temperature off the step of 0.1 or outside 30.0–37.0", () => {
  for (const value of [36.55, 29.9, 37.1, 36.61, -1, 100]) {
    refused(temperatureBelow(value));
  }
});

test("the check takes the whole numbers of „Tu leży mniej niż” as before, and only those", () => {
  for (const value of [0, 1, 7, 50]) {
    for (const condition of held(hereBelow(value)))
      assert.deepEqual(condition, hereBelow(value));
  }
  for (const value of [1.5, 0.1, -1, 51]) refused(hereBelow(value));
});

test("the check takes each new kind's numbers from its minimum to its maximum on its step", () => {
  const ranges = [
    [satietyBelow, 0, 100],
    [healthBelow, 0, 100],
    [opponentHealthBelow, 0, 100],
    [(value) => itemBelow(firstItem, value), 0, 50],
    [campfireLeftBelow, 0, 120],
  ];
  for (const [make, min, max] of ranges) {
    for (const value of [min, max, min + 1, max - 1]) {
      for (const condition of held(make(value)))
        assert.deepEqual(condition, make(value));
    }
    for (const value of [min - 1, max + 1, min + 0.5, max - 0.1]) {
      refused(make(value));
    }
  }
});

test("the check refuses a number that is no finite number, for every kind that takes one", () => {
  const makers = [
    temperatureBelow,
    satietyBelow,
    healthBelow,
    opponentHealthBelow,
    (value) => itemBelow(firstItem, value),
    campfireLeftBelow,
    hereBelow,
  ];
  for (const make of makers) {
    for (const value of [
      Number.NaN,
      Infinity,
      -Infinity,
      "20",
      null,
      undefined,
    ])
      refused(make(value));
  }
});

test("„Zapas poniżej” takes every item of the data, and nothing else", () => {
  for (const item of Object.keys(ITEMS)) {
    for (const condition of held(itemBelow(item, 8)))
      assert.deepEqual(condition, itemBelow(item, 8));
  }
  for (const item of ["granite", "toString", "", 0, undefined]) {
    refused(itemBelow(item, 8));
  }
});

test("„Z dala od — ognisko” takes no number and no target", () => {
  for (const condition of held(AWAY)) assert.deepEqual(condition, AWAY);
  for (const condition of held({ ...AWAY, value: 3 }))
    assert.deepEqual(condition, AWAY);
  for (const condition of held(ALWAYS)) assert.deepEqual(condition, ALWAYS);
});

